/**
 * Drag and Drop support for Solid-JS.
 *
 * Provides 3 components, <DragAndDrop>, <Draggable>, <Dropzone> that implements a system for dragging draggables and dropping them
 * into drop zones.
 *
 * This system is specifically engineered for dragging items and dropping into dropzones.  For simple draggables, consider using <DragHandle> instead as that will provide
 * the raw methods for dragging.
 *
 */

enum debugLevels {
	Log = 0,
	Verbose = 1,
	VeryVerbose = 2,
}
const DEBUG_LEVEL = debugLevels.Log;
import {
	Accessor,
	createEffect,
	createMemo,
	createSignal,
	JSX,
	onCleanup,
	untrack,
	type ParentComponent,
	type ParentProps,
} from "solid-js";
import { createContext, useContext } from "solid-js";
import { Portal } from "solid-js/web";

import { InputEngineEvent } from "#core/ui/input/input-support.js";
import { ActiveInputDevice } from "#core/ui-next/services/input.js";

export interface DraggableData {
	/** An optional debug string. */
	debugId?: string;

	/** A unique identifier used by the internals of the drag-drop system. */
	id: symbol;

	/** The data payload of the draggable. */
	data: unknown;
}

export interface DropzoneData {
	/** An optional debug string. */
	debugId?: string;

	/** A unique identifier used by the internals of the drag-drop system. */
	id: symbol;

	/** The data payload of the dropzone. */
	data: unknown;
}

export enum DragEndStatus {
	/** The draggable was released but not into any drop zone. */
	Released,

	/**
	 * The drag operation was cancelled.
	 * This could happen if the `disabled` flag is toggled mid-drag or if explicitly cancelled.
	 * */
	Cancelled,

	/**
	 * The draggable was dropped into and accepted by a dropzone.
	 */
	AcceptedByDropzone,

	/**
	 * The draggable was dropped into yet rejected by a dropzone.
	 */
	RejectedByDropzone,
}

export type DragStartCallback = (draggable: DraggableData, position: { x: number; y: number }) => void;

export type DragEndCallback = (
	/** The draggable. */
	draggable: DraggableData,

	/** The final status of the drag operation. */
	status: DragEndStatus,

	/** The referenced dropzone when the status is either `AcceptedByDropzone` or `RejectedByDropzone` */
	zone?: DropzoneData,

	/**
	 * The position of the draggable when the operation ended.
	 * This may not always be populated, depending on how the operation was aended.
	 */
	position?: { x: number; y: number },
) => void;

export type DragDropCallback = (
	/** The draggable being dropped. */
	draggable: DraggableData,

	/** The zone the draggable is dropped into.*/
	dropzone: DropzoneData,

	/** The position of the draggable as it was dropped. */
	position?: { x: number; y: number },
) => void;

export type DragDropPredicate = (draggable: DraggableData, dropzone: DropzoneData) => Accessor<boolean>;

export interface DragAndDropGlobalContextValue {
	/**
	 * Disables all drag and drop systems within this context.
	 */
	disabled: boolean;

	/**
	 * Parent element of the overlay.
	 */
	overlayParent: HTMLElement;
}

export const DragAndDropGlobalContext = createContext<DragAndDropGlobalContextValue>({
	disabled: false,
	overlayParent: document.body,
});

export const useDragAndDropGlobalContext = () => useContext(DragAndDropGlobalContext);

/**
 * Public context to access DragAndDrop data.
 */
interface DragAndDropContextValue {
	/* Signal communicating that the drag and drop functionality is disabled. */
	isDisabled: Accessor<boolean>;

	/* Signal communicating that a draggable is being dragged. */
	isDragging: Accessor<DraggableData | null>;

	/* Signal communicating that a draggable is being dropped. */
	isDropping: Accessor<{
		draggable: DraggableData;
		dropzone: DropzoneData;
		position: { x: number; y: number };
	} | null>;

	/** The dropzone which the draggable is currently over. */
	overDropzone: Accessor<{
		dropzone: DropzoneData;
		canDrop: Accessor<boolean>;
	} | null>;
}

export const DragAndDropContext = createContext<DragAndDropContextValue>({
	isDisabled: () => false,
	isDragging: () => null,
	isDropping: () => null,
	overDropzone: () => null,
});
export const useDragAndDropContext = () => useContext(DragAndDropContext);

/**
 * Private context between <DragAndDrop>, <Draggable>, and <DropZone>
 */
interface DragAndDropInternalContextValue {
	captureDraggable: (
		draggable: DraggableData,
		x: number,
		y: number,
		startCallback?: DragStartCallback,
		endCallback?: DragEndCallback,
		canDropPredicate?: DragDropPredicate,
	) => void;

	releaseDraggable: (x: number, y: number) => void;

	cancelDrag: () => void;

	enterDropzone: (
		dropzone: DropzoneData,
		el: HTMLElement,
		canDrop: Accessor<boolean>,
		x: number,
		y: number,
	) => boolean;

	leaveDropzone: (dropzone: DropzoneData, el: HTMLElement, x: number, y: number) => boolean;

	portalRoot: HTMLElement | null;

	dropPredicate: Accessor<DragDropPredicate | null>;
}

const DoNothing = () => {
	/* do nothing*/
};
const DragAndDropInternalContext = createContext<DragAndDropInternalContextValue>({
	captureDraggable: DoNothing,
	releaseDraggable: DoNothing,
	cancelDrag: DoNothing,
	enterDropzone: () => false,
	leaveDropzone: () => false,
	portalRoot: null,
	dropPredicate: () => null,
});

const useDragAndDropInternalContext = () => useContext(DragAndDropInternalContext);

export function setElementPositionViaTopLeft(el: HTMLElement, x: number, y: number) {
	// Gameface optimization. Using topPX/leftPX avoids unnecessary string creation and GC churn.
	//el.style.top = `${y}px`;
	//el.style.left = `${x}px`;
	el.style.topPX = y;
	el.style.leftPX = x;
}

export function setElementPositionViaTransform(el: HTMLElement, x: number, y: number) {
	el.style.transform = `translate(${x}px, ${y}px)`;

	// TODO - Gameface optimization.
	//el.style.setTranslate2D(x, y);
}
export const defaultSetElementPosition = setElementPositionViaTransform;

//#region <DragAndDrop>
export interface DragAndDropProps {
	/**
	 * Optional callback invoked when a draggable starts to be dragged.
	 * This is equivilent to `Draggable.onDragStart`.
	 */
	onDragStart?: DragStartCallback;

	/**
	 * Optional callback invoked when a draggable starts to be dragged.
	 * This is equivilent to `Draggable.onDragEnd`.
	 */
	onDragEnd?: DragEndCallback;

	/**
	 * Optional.  Returns a boolean signal dictating if the draggable is allowed to be dropped into this zone.
	 * NOTE: This method is invoked when dragging begins for each drop zone.
	 */
	canDrop?: DragDropPredicate;

	/** Optional. Called when a draggable is dropped into a zone. */
	onDragDrop?: DragDropCallback;

	/**
	 * Optional property to restrict movement of draggables.
	 * Restriction can be bound to a specific axis, a specific rect, or function
	 * Values are in pixels and are in client space.
	 */
	restrict?:
		| "x"
		| "y"
		| ((x: number, y: number) => { x: number; y: number })
		| { top: number; left: number; bottom: number; right: number };

	/**
	 * The parent to attach the draggable overlay elements to.
	 * By default, this will fallback to `document.body` however it is good practice to specify this.
	 */
	overlayParent?: HTMLElement;

	/**
	 * Override the callback to adjust the overlay position.
	 * There are several provided implementation exported.
	 * If nothing is provided, the default implementation will be used.
	 */
	setElementPosition?: (el: HTMLElement, x: number, y: number) => void;

	/**
	 * Disables drag and drop functionality for all nested draggables and drop zones.
	 * Default: false
	 */
	disabled?: boolean;

	/**
	 * Outputs debug messages to the console to help diagnose issues.
	 */
	debugTrace?: boolean;
}

export const DragAndDrop: ParentComponent<DragAndDropProps> = (props) => {
	const [isCaptured, setIsCapture] = createSignal<DraggableData | null>(null);
	const [isDragging, setIsDragging] = createSignal<DraggableData | null>(null);
	const [isDropping, setIsDropping] = createSignal<{
		draggable: DraggableData;
		dropzone: DropzoneData;
		position: { x: number; y: number };
	} | null>(null);

	const [draggableCanDropPredicate, setDraggableCanDropPredicate] = createSignal<DragDropPredicate | null>(null);

	/**
	 * Represents all of the dropzones that the current draggable is over.
	 * Sorted by depth such that the last item in the array is the most deeply nested zone.
	 */
	const [dropzones, setDropzones] = createSignal<
		{
			dropzone: DropzoneData;
			canDrop: Accessor<boolean>;
			ref: HTMLElement;
		}[]
	>([]);

	/**
	 * The most deeply nested zone, aka the last item in dropzones().
	 * NOTE: In the future, this may change.  We may allow drop-zones to set themselves up as 'passthrough' such that if they
	 * reject the draggable, it will pass through the zone and into the next nested zone.
	 */
	const dropzone = createMemo(() => {
		const items = dropzones();
		if (items.length > 0) {
			return items[items.length - 1];
		} else {
			return null;
		}
	});

	const activeCanDropPredicate = createMemo(() => {
		const draggable = isDragging();
		if (draggable) {
			const draggablePredicate = draggableCanDropPredicate();
			if (props.canDrop && draggablePredicate) {
				// Create a new function that merges the results.
				const topLevel = props.canDrop;
				const draggableLevel = draggablePredicate;

				const merged: DragDropPredicate = (draggable, dropzone) => {
					const topLevelAccessor = topLevel(draggable, dropzone);
					const draggableAccessor = draggableLevel(draggable, dropzone);
					const memo = createMemo(() => {
						const top = topLevelAccessor();
						const drag = draggableAccessor();
						return top && drag;
					});
					return memo;
				};
				return merged;
			} else if (props.canDrop) {
				return props.canDrop;
			} else {
				return draggablePredicate;
			}
		} else {
			// No predicates needed if we're not dragging anything.
			return null;
		}
	});

	const globalContext = useDragAndDropGlobalContext();

	const overlayRoot = document.createElement("div");
	overlayRoot.style.position = "absolute";
	overlayRoot.style.pointerEvents = "none";

	const overlayContent = document.createElement("div");
	overlayContent.style.transform = "translate(-50%, -50%)";
	overlayRoot.appendChild(overlayContent);

	let capturedStartCallback: DragStartCallback | undefined | null = null;
	let capturedEndCallback: DragEndCallback | undefined | null = null;
	let currentDropzoneElement: Element | null;

	window.addEventListener("engine-input", onEngineInputCapture, { capture: true });
	onCleanup(() => {
		window.removeEventListener("engine-input", onEngineInputCapture, { capture: true });
	});

	function onEngineInputCapture(event: InputEngineEvent) {
		let handled = false;
		debugTrace(debugLevels.VeryVerbose, "onInputAction:", event.detail);
		if (event.detail.name === "touch-pan" && event.detail.status === InputActionStatuses.DRAG) {
			onMouseOrTouchMove(event.detail.x, event.detail.y);
			if (!isDragging()) {
				return;
			}
			debugTrace(
				debugLevels.VeryVerbose,
				"onInputAction:",
				"touch-pan",
				InputActionStatuses.UPDATE,
				`[${event.detail.x}, ${event.detail.y}]`,
			);
			const elementsAtPoint = document.elementsFromPoint(event.detail.x, event.detail.y);
			const el = elementsAtPoint.find((el) => el.classList.contains("dropzone")) ?? null;

			if (el !== currentDropzoneElement) {
				if (currentDropzoneElement && currentDropzoneElement.contains(el) === false) {
					debugTrace(
						debugLevels.Log,
						"onInputAction: leaving dropzone",
						currentDropzoneElement,
						`[${event.detail.x}, ${event.detail.y}]`,
					);
					currentDropzoneElement.dispatchEvent(new MouseEvent("mouseleave", { bubbles: true }));
				}
				currentDropzoneElement = el;
				if (currentDropzoneElement) {
					debugTrace(
						debugLevels.Log,
						"onInputAction: entering dropzone",
						currentDropzoneElement,
						`[${event.detail.x}, ${event.detail.y}]`,
					);
					currentDropzoneElement.dispatchEvent(new MouseEvent("mouseenter", { bubbles: true }));
				}
			}
			handled = true;
		}
		if (event.detail.name === "touch-complete" && event.detail.status === InputActionStatuses.FINISH) {
			debugTrace(
				debugLevels.Verbose,
				"onInputAction:",
				"touch-complete",
				InputActionStatuses.FINISH,
				`[${event.detail.x}, ${event.detail.y}]`,
			);
			releaseDraggable(event.detail.x, event.detail.y);
			handled = true;
		}
		if (handled) {
			event.preventDefault();
			event.stopPropagation();
		}
	}

	const isDisabled = createMemo(() => {
		const activeInputDevice = ActiveInputDevice();
		let inputSupportsDND = false;
		switch (activeInputDevice) {
			case InputDeviceType.Mouse:
			case InputDeviceType.Touch:
			case InputDeviceType.Hybrid:
				inputSupportsDND = true;
				break;
		}

		return inputSupportsDND == false || globalContext.disabled === true || props.disabled === true;
	});

	const overlayParent = createMemo(() => {
		return props.overlayParent ?? globalContext.overlayParent;
	});

	const initialPosition = {
		x: 0,
		y: 0,
	};

	const shouldDebugTrace = untrack(() => props.debugTrace);

	function debugTrace(debugLevel: debugLevels, ...args: unknown[]): void {
		if (!shouldDebugTrace || debugLevel > DEBUG_LEVEL) {
			return;
		}
		console.debug(`[${Date.now()}] DnD: DragAndDrop`, ...args);
	}

	function resetDrag() {
		debugTrace(debugLevels.Verbose, "resetDrag");
		setIsCapture(null);
		setIsDropping(null);
		setIsDragging(null);
		setDropzones([]);
		overlayRoot.style.display = "none";
		overlayRoot.remove();
		currentDropzoneElement = null;
	}

	function startDrag(x: number, y: number) {
		debugTrace(debugLevels.Verbose, "startDrag", `[${x}, ${y}]`);
		if (isDragging()) {
			throw new Error("Already in a dragging operation!");
		}

		const draggable = isCaptured();
		if (draggable == null) {
			throw new Error("Cannot start a drag operation when no draggable has been captured.");
		}

		debugTrace(debugLevels.Verbose, "Starting drag operation.", draggable);

		setIsDragging(draggable);

		if (props.onDragStart) {
			props.onDragStart(draggable, initialPosition);
		}

		if (capturedStartCallback) {
			capturedStartCallback(draggable, initialPosition);
		}

		const setPosition = props.setElementPosition ?? defaultSetElementPosition;
		setPosition(overlayRoot, x, y);

		overlayRoot.style.display = "";
		overlayParent().appendChild(overlayRoot);
	}

	function captureDraggable(
		draggable: DraggableData,
		x: number,
		y: number,
		startCallback?: DragStartCallback,
		endCallback?: DragEndCallback,
		canDropPredicate?: DragDropPredicate,
	) {
		debugTrace(debugLevels.Verbose, "captureDraggable", draggable, `[${x}, ${y}]`);
		if (isDragging()) {
			throw new Error("Already in a dragging operation!");
		}

		if (props.disabled) {
			return;
		}

		setIsCapture(draggable);

		capturedStartCallback = startCallback;
		capturedEndCallback = endCallback;

		if (canDropPredicate) {
			setDraggableCanDropPredicate(() => canDropPredicate);
		} else {
			setDraggableCanDropPredicate(null);
		}

		const setPosition = props.setElementPosition ?? defaultSetElementPosition;
		setPosition(overlayRoot, x, y);

		initialPosition.x = x;
		initialPosition.y = y;
	}

	function releaseDraggable(x: number, y: number) {
		debugTrace(debugLevels.Verbose, "releaseDraggable", `[${x}, ${y}]`);
		const draggable = isDragging();
		const position = { x: x, y: y };

		// A draggable was likely 'captured' but the pointer did not move so it wasn't 'dragging'.
		if (draggable == null) {
			resetDrag();
			return;
		}

		const dz = dropzone();

		let status = DragEndStatus.Released;
		if (dz) {
			if (dz.canDrop()) {
				status = DragEndStatus.AcceptedByDropzone;
			} else {
				status = DragEndStatus.RejectedByDropzone;
			}
		}

		if (props.debugTrace) {
			let statusText = "";
			switch (status) {
				case DragEndStatus.Released:
					statusText = "Released";
					break;

				/*case DragEndStatus.Cancelled:
					statusText = "Cancelled";
					break;*/

				case DragEndStatus.AcceptedByDropzone:
					statusText = "Accepted";
					break;
				case DragEndStatus.RejectedByDropzone:
					statusText = "Rejected";
					break;
			}

			debugTrace(debugLevels.Log, "Ending Drag Operation.", statusText, draggable, dz?.dropzone);
		}

		if (dz && dz.canDrop()) {
			// Will invoke callbacks within Draggable and Dropzone.
			setIsDropping({
				draggable: draggable,
				dropzone: dz.dropzone,
				position: position,
			});

			if (props.onDragDrop) {
				props.onDragDrop(draggable, dz.dropzone, position);
			}
		}

		if (capturedEndCallback) {
			capturedEndCallback(draggable, status, dz?.dropzone, position);
			capturedEndCallback = null;
		}

		if (props.onDragEnd) {
			props.onDragEnd(draggable, status, dz?.dropzone, position);
		}

		resetDrag();
	}

	function cancelDrag() {
		debugTrace(debugLevels.Verbose, "cancelDrag");
		const draggable = isDragging();
		if (draggable) {
			if (capturedEndCallback) {
				capturedEndCallback(draggable, DragEndStatus.Cancelled);
				capturedEndCallback = null;
			}
		}

		resetDrag();
	}

	function enterDropzone(
		dropzone: DropzoneData,
		el: HTMLElement,
		canDrop: Accessor<boolean>,
		_x: number,
		_y: number,
	) {
		const original = dropzones();

		// If this drop zone is already the in the list, do nothing.
		// This likely is the result of a redundant `enterDropzone` call.
		if (original.find((z) => z.dropzone.id === dropzone.id)) {
			return false;
		}

		const zones = original.filter((z) => {
			const zoneIsChildOfElement = el.contains(z.ref);
			const elementIsChildOfZone = z.ref.contains(el);
			return !zoneIsChildOfElement && elementIsChildOfZone;
		});
		zones.push({ dropzone: dropzone, ref: el, canDrop: canDrop });

		if (props.debugTrace) {
			const t = zones.length > 1 ? "nested dropzone" : "dropzone";
			debugTrace(debugLevels.Log, `enterDropzone Entering ${t}.`, dropzone, canDrop());
		}

		setDropzones(zones);
		return true;
	}

	function leaveDropzone(dz: DropzoneData, _el: HTMLElement, _x: number, _y: number) {
		const current_dz = dropzone();
		if (current_dz && current_dz.dropzone.id != dz.id) {
			console.warn("Leaving a drop zone that is not the active drop zone??");
		}

		const original = dropzones();
		const zones = original.filter((z) => z.dropzone.id != dz.id);
		if (original.length != zones.length) {
			if (props.debugTrace) {
				debugTrace(debugLevels.Log, "leaveDropzone: Leaving Dropzone.", dz);

				if (zones.length > 0) {
					const newZone = zones[zones.length - 1];
					debugTrace(
						debugLevels.Log,
						"leaveDropzone: Still within dropzone.",
						newZone.dropzone,
						newZone.canDrop(),
					);
				}
			}

			setDropzones(zones);
		} else {
			console.warn("Leaving a dropzone that we weren't inside?");
			return false;
		}

		return true;
	}

	function onMouseOrTouchMove(x: number, y: number) {
		debugTrace(
			debugLevels.VeryVerbose,
			"onMouseOrTouchMove:",
			`[${x}, ${y}]`,
			"isDragging:",
			isDragging(),
			"isCaptured:",
			isCaptured(),
		);
		if (isDragging() == null && isCaptured()) {
			startDrag(x, y);
		}

		let newX = x;
		let newY = y;

		if (props.restrict === "x") {
			newY = initialPosition.y;
		} else if (props.restrict === "y") {
			newX = initialPosition.x;
		} else if (typeof props.restrict == "function") {
			const result = props.restrict(newX, newY);
			newX = result.x;
			newY = result.y;
		} else if (props.restrict) {
			const bounds = props.restrict;
			newX = Math.max(bounds.left, Math.min(newX, bounds.right));
			newY = Math.max(bounds.top, Math.min(newY, bounds.bottom));
		}

		const setPosition = props.setElementPosition ?? defaultSetElementPosition;
		setPosition(overlayRoot, x, y);
	}

	function handleMouseMove(event: MouseEvent) {
		debugTrace(debugLevels.VeryVerbose, "handleMouseMove");
		onMouseOrTouchMove(event.clientX, event.clientY);
	}

	function handleMouseUp(event: MouseEvent) {
		debugTrace(debugLevels.Verbose, "handleMouseUp");
		releaseDraggable(event.clientX, event.clientY);
	}

	createEffect(() => {
		if (isDisabled() && isDragging()) {
			cancelDrag();
		}
	});

	let listeningForMouseEvents = false;
	createEffect(() => {
		if (ActiveInputDevice() !== InputDeviceType.Mouse) {
			return;
		}
		if (isCaptured()) {
			debugTrace(
				debugLevels.Verbose,
				"DragAndDrop: isCaptured changed to true. Adding mouse listeners for move and up",
			);
			listeningForMouseEvents = true;
			document.addEventListener("mousemove", handleMouseMove);
			document.addEventListener("mouseup", handleMouseUp);
		} else {
			debugTrace(
				debugLevels.Verbose,
				"DragAndDrop: isCaptured changed to false. Removing mouse listeners for move and up",
			);
			listeningForMouseEvents = false;
			document.removeEventListener("mousemove", handleMouseMove);
			document.removeEventListener("mouseup", handleMouseUp);
		}

		onCleanup(() => {
			if (listeningForMouseEvents) {
				debugTrace(debugLevels.Verbose, "DragAndDrop: onCleanup. Removing mouse listeners for move and up");
				document.removeEventListener("mousemove", handleMouseMove);
				document.removeEventListener("mouseup", handleMouseUp);
			}
		});
	});

	return (
		<DragAndDropContext.Provider
			value={{
				isDisabled: isDisabled,
				isDragging: isDragging,
				isDropping: isDropping,
				overDropzone: dropzone,
			}}
		>
			<DragAndDropInternalContext.Provider
				value={{
					captureDraggable,
					releaseDraggable,
					cancelDrag,
					enterDropzone,
					leaveDropzone,
					portalRoot: overlayContent,
					dropPredicate: activeCanDropPredicate,
				}}
			>
				<div class="drag-and-drop flex-auto">{props.children}</div>
			</DragAndDropInternalContext.Provider>
		</DragAndDropContext.Provider>
	);
};
//#endregion
//#region <Draggable>
interface DraggableContextValue {
	draggable: Accessor<DraggableData> | null;

	/** Set to true when components are being used to render the overlay. */
	isRenderingOverlay: boolean;

	/** True if this draggable is currently being dragged. */
	isDragging: Accessor<boolean>;
}

export const DraggableContext = createContext<DraggableContextValue>({
	draggable: null,
	isRenderingOverlay: false,
	isDragging: () => false,
});

export const useDraggableContext = () => useContext(DraggableContext);

export interface DraggableProps {
	/**
	 * Optional debug string.  This is not directly used anywhere in the drag and drop system, but useful for debugging.
	 */
	debugId?: string;

	/**
	 * The payload of the draggable.  This typically contains data specific to the draggable.
	 * It is recommended to include some sort of well-defined discriminator and type guards to assist in narrowing the type.
	 */
	data?: unknown;

	/**
	 * Optional.  Invoked when dragging begins.
	 */
	onDragStart?: DragStartCallback;

	/**
	 * Optional. Invoked when dragging ends.
	 */
	onDragEnd?: DragEndCallback;

	/**
	 * Returns a boolean signal dictating if the draggable is allowed to be dropped into this zone.
	 * NOTE: This method is invoked when dragging begins for each drop zone.
	 */
	canDrop?: DragDropPredicate;

	/** Optional. Called when a draggable is dropped into a zone. */
	onDragDrop?: DragDropCallback;

	/**
	 * Disables the draggable, preventing it from being dragged.
	 * Default: false
	 */
	disabled?: boolean;

	/**
	 * Style applied on the element left behind when dragging.
	 * Default: false
	 */
	ghostElementStyle?: string | JSX.CSSProperties;

	debugTrace?: boolean;
}

export const Draggable: ParentComponent<DraggableProps> = (props) => {
	const id = Symbol();
	const context = useDragAndDropContext();
	const internalContext = useDragAndDropInternalContext();

	const draggableContext = useDraggableContext();
	if (draggableContext.draggable != null) {
		throw new Error("<Draggable> components must not be nested.");
	}
	const shouldDebugTrace = untrack(() => props.debugTrace);
	const debugId = untrack(() => props.debugId);

	function debugTrace(debugLevel: debugLevels, ...args: unknown[]): void {
		if (!shouldDebugTrace || debugLevel > DEBUG_LEVEL) {
			return;
		}
		console.debug(`[${Date.now()}] DnD: Draggable ([${debugId ?? "no id"})`, ...args);
	}

	engine.on("InputAction", onInputAction);
	onCleanup(() => {
		engine.off("InputAction", onInputAction);
	});

	function onInputAction(name: string, status: InputActionStatuses, x: number, y: number) {
		if (status !== InputActionStatuses.FINISH || name !== "touch-tap") {
			return;
		}

		if (name === "touch-tap") {
			debugTrace(debugLevels.Log, "onInputAction:", name, status, `[${x}, ${y}]`);
			stopDrag(x, y);
		}
	}

	function startDrag(x: number, y: number) {
		debugTrace(debugLevels.Verbose, "startDrag:", `[${x}, ${y}]`);
		if (isDisabled() || context.isDragging()) {
			return;
		}

		internalContext.captureDraggable(
			{ id: id, data: props.data, debugId: props.debugId },
			x,
			y,
			props.onDragStart,
			props.onDragEnd,
			props.canDrop,
		);
	}

	function stopDrag(x: number, y: number) {
		debugTrace(debugLevels.Verbose, "stopDrag:", `[${x}, ${y}]`);
		internalContext.releaseDraggable(x, y);
	}

	function handleMouseDown(event: MouseEvent) {
		debugTrace(debugLevels.Verbose, "handleMouseDown");
		startDrag(event.clientX, event.clientY);
	}

	function handleTouchStart(event: TouchEvent) {
		debugTrace(debugLevels.Verbose, "handleTouchStart");
		if (event.touches.length > 0) {
			startDrag(event.touches[0].clientX, event.touches[0].clientY);
		}
	}

	function handleMouseClick(event: MouseEvent) {
		debugTrace(debugLevels.Verbose, "handleMouseClick");
		stopDrag(event.clientX, event.clientY);
	}

	const isDisabled = createMemo(() => {
		return context.isDisabled() || props.disabled === true;
	});

	const isDragging = createMemo(() => {
		const dragging = context.isDragging();
		return dragging != null && dragging.id == id;
	});

	const isDropping = createMemo(() => {
		const dropping = context.isDropping();
		if (dropping && dropping.draggable.id == id) {
			return dropping;
		} else {
			return null;
		}
	});

	createEffect(() => {
		if (props.onDragDrop) {
			const drop = isDropping();
			if (drop) {
				props.onDragDrop(drop.draggable, drop.dropzone, drop.position);
			}
		}
	});

	const draggable = createMemo(() => {
		return { id: id, data: props.data, debugId: props.debugId };
	});

	return (
		<DraggableContext.Provider
			value={{
				draggable: draggable,
				isRenderingOverlay: false,
				isDragging: isDragging,
			}}
		>
			<div
				style={isDragging() ? props.ghostElementStyle : ""}
				onMouseDown={handleMouseDown}
				onClick={handleMouseClick}
				onTouchStart={handleTouchStart}
			>
				{props.children}
				{isDragging() && (
					<Portal mount={internalContext.portalRoot!}>
						<DraggableContext.Provider
							value={{
								draggable: draggable,
								isRenderingOverlay: true,
								isDragging,
							}}
						>
							{props.children}
						</DraggableContext.Provider>
					</Portal>
				)}
			</div>
		</DraggableContext.Provider>
	);
};
//#endregion

//#region <Dropzone>
interface DropzoneProps {
	/**
	 * Optional debug string.  This is not directly used anywhere in the drag and drop system, but useful for debugging.
	 */
	debugId?: string;

	/**
	 * The payload of the draggable.  This typically contains data specific to the draggable.
	 * It is recommended to include some sort of well-defined discriminator and type guards to assist in narrowing the type.
	 */
	data?: unknown;

	/**
	 * Returns a boolean signal dictating if the draggable is allowed to be dropped into this zone.
	 * NOTE: This method is invoked when dragging begins.
	 */
	canDrop?: DragDropPredicate;

	/** Optional. Called when a draggable is dropped into this zone. */
	onDragDrop?: DragDropCallback;

	/**
	 * Optional.  Invoked when a draggable is over a zone.
	 * NOTE: The order of these callbacks for nested zones is not guarenteed.
	 * NOTE: For nested zones, when leaving a nested, `onOver` is not invoked for the parent zone a second time.
	 */
	onDragOver?: (draggable: DraggableData, dropzone: DropzoneData, x: number, y: number) => void;

	/**
	 * Optional. Invoked when a draggable leaves the zone.
	 * NOTE: The order of these callbacks for nested zones is not guarenteed.
	 * NOTE: When entering a nested tooltip, this callback is not invoked for the parent.
	 */
	onDragLeave?: (draggable: DraggableData, dropzone: DropzoneData, x: number, y: number) => void; // Called when a draggable leaves this zone

	/**
	 * If this is a nested dropzone and the draggable cannot be dropped into this zone, can it pass through to the parent zone?
	 * Default: false
	 */
	passthroughOnFailure?: boolean;

	/**
	 * Disables the dropzone.
	 * Default: false
	 * No callbacks are invoked for disabled zones.
	 * Nested drop zones will pass through to their parent zones.
	 */
	disabled?: boolean;

	/** Optional. Passed to the div that wraps the dropzone. */
	class?: string;

	/** Optional. Passed to the div that wraps the dropzone. */
	classList?: // eslint-disable-next-line @typescript-eslint/consistent-indexed-object-style
	| {
				[k: string]: boolean | undefined;
		  }
		| undefined;

	debugTrace?: boolean;
}

interface DropzoneContextValue {
	dropzone: Accessor<DropzoneData | null>;
	canDrop: Accessor<boolean | null>;
}

export const DropzoneContext = createContext<DropzoneContextValue>({
	dropzone: () => null,
	canDrop: () => null,
});

export const useDropzoneContext = () => useContext(DropzoneContext);

export const Dropzone: ParentComponent<DropzoneProps> = (props) => {
	const context = useDragAndDropContext();
	const internalContext = useDragAndDropInternalContext();
	const [_hovering, setHovering] = createSignal<{
		id: symbol;
		data: unknown;
	} | null>(null);

	const [localCanDrop, setLocalCanDrop] = createSignal<Accessor<boolean> | null>(null);
	const [contextCanDrop, setContextCanDrop] = createSignal<Accessor<boolean> | null>(null);

	const shouldDebugTrace = untrack(() => props.debugTrace);
	const debugId = untrack(() => props.debugId);

	function debugTrace(debugLevel: debugLevels, ...args: unknown[]): void {
		if (!shouldDebugTrace || debugLevel > DEBUG_LEVEL) {
			return;
		}
		console.debug(`[${Date.now()}] DnD: Dropzone (${debugId ?? "no id"})`, ...args);
	}

	createEffect(() => {
		if (props.canDrop) {
			const draggable = context.isDragging();
			if (draggable) {
				const dropzone = { id: id, data: props.data, debugId: props.debugId };
				const signalAccessor = props.canDrop(draggable, dropzone);
				setLocalCanDrop(() => signalAccessor);
			}
		} else {
			setLocalCanDrop(null);
		}
	});

	createEffect(() => {
		const predicate = internalContext.dropPredicate();
		if (predicate) {
			const draggable = context.isDragging();
			if (draggable) {
				const dropzone = { id: id, data: props.data, debugId: props.debugId };
				const signalAccessor = predicate(draggable, dropzone);
				setContextCanDrop(() => signalAccessor);
			}
		} else {
			setContextCanDrop(null);
		}
	});

	const canDrop = createMemo(() => {
		const local = localCanDrop();
		const context = contextCanDrop();

		if (local && local() == false) {
			return false;
		}

		if (context && context() == false) {
			return false;
		}

		return true;
	});

	const id = Symbol();
	let dropzoneDiv: HTMLDivElement | undefined;

	const isDisabled = createMemo(() => {
		return context.isDisabled() || props.disabled === true;
	});

	createEffect(() => {
		if (context.isDragging() == null || props.disabled === true) {
			setHovering(null);
		}
	});

	createEffect(() => {
		if (props.onDragDrop) {
			const dropped = context.isDropping();
			if (dropped && dropped.dropzone.id == id) {
				props.onDragDrop(dropped.draggable, dropped.dropzone, dropped.position);
			}
		}
	});

	function onEnterDropzone(x: number, y: number) {
		debugTrace(debugLevels.Verbose, "onEnterDropzone:", `[${x}, ${y}]`, "isDisabled:", isDisabled());
		/**
		 * COHERENT GAMEFACE NOTE - For reasons I cannot determine, `onMouseEnter` is triggered several times using the same event payload (same target and related target).
		 * Because of this, we must check whether or not `enterDropzone` returns true before logging anything or reacting to the entry.
		 * This issue does not seem to occur in `onMouseLeave`.
		 */
		if (isDisabled()) {
			return;
		}

		const dragging = context.isDragging();
		if (dragging != null && dropzoneDiv) {
			const dropzone = { id: id, data: props.data, debugId: props.debugId };
			if (internalContext.enterDropzone(dropzone, dropzoneDiv, canDrop, x, y)) {
				setHovering(dragging);
			}

			if (props.onDragOver) {
				props.onDragOver(dragging, dropzone, x, y);
			}
		}
	}

	function handleMouseEnter(event: MouseEvent) {
		debugTrace(debugLevels.Verbose, "handleMouseEnter");
		onEnterDropzone(event.clientX, event.clientY);
	}

	function onExitDropZone(x: number, y: number) {
		debugTrace(debugLevels.Verbose, "onExitDropZone:", `[${x}, ${y}]`, "isDisabled:", isDisabled());
		if (isDisabled()) {
			return;
		}

		const dragging = context.isDragging();
		if (dragging != null && dropzoneDiv) {
			const dropzone = { id: id, data: props.data, debugId: props.debugId };
			if (internalContext.leaveDropzone(dropzone, dropzoneDiv, x, y)) {
				if (props.onDragLeave) {
					props.onDragLeave(dragging, dropzone, x, y);
				}
			}
		}

		setHovering(null);
	}

	function handleMouseLeave(event: MouseEvent) {
		debugTrace(debugLevels.Verbose, "handleMouseLeave");
		onExitDropZone(event.clientX, event.clientY);
	}

	const dropzone = createMemo(() => {
		return { id: id, data: props.data, debugId: props.debugId };
	});

	return (
		<DropzoneContext.Provider
			value={{
				dropzone: dropzone,
				canDrop: canDrop,
			}}
		>
			<div
				class={`${props.class ?? ""} dropzone`}
				classList={props.classList}
				ref={dropzoneDiv}
				onMouseEnter={handleMouseEnter}
				onMouseLeave={handleMouseLeave}
			>
				{props.children}
			</div>
		</DropzoneContext.Provider>
	);
};
//#endregion

//#region Typed Components
/**
 * Experimenting with typed components that will narrow the `unknown` data field to something specific across the board.
 */
export interface DraggableDataT<T> extends Omit<DraggableData, "data"> {
	data: T;
}

export interface DropzoneDataT<T> extends Omit<DropzoneData, "data"> {
	data: T;
}

export type DragStartCallbackT<T> = (draggable: DraggableDataT<T>, position: { x: number; y: number }) => void;

export type DragEndCallbackT<T> = (
	/** The draggable. */
	draggable: DraggableDataT<T>,

	/** The final status of the drag operation. */
	status: DragEndStatus,

	/** The referenced dropzone when the status is either `AcceptedByDropzone` or `RejectedByDropzone` */
	zone?: DropzoneData,

	/**
	 * The position of the draggable when the operation ended.
	 * This may not always be populated, depending on how the operation was aended.
	 */
	position?: { x: number; y: number },
) => void;

export type DragDropCallbackT<DraggableType, DropzoneType> = (
	/** The draggable being dropped. */
	draggable: DraggableDataT<DraggableType>,

	/** The zone the draggable is dropped into.*/
	dropzone: DropzoneDataT<DropzoneType>,

	/** The position of the draggable as it was dropped. */
	position?: { x: number; y: number },
) => void;

export type DragDropPredicateT<DraggableType, DropzoneType> = (
	draggable: DraggableDataT<DraggableType>,
	dropzone: DropzoneDataT<DropzoneType>,
) => Accessor<boolean>;

export interface DraggablePropsT<DraggableDataType, DropzoneDataType> extends DraggableProps {
	/**
	 * The payload of the draggable.  This typically contains data specific to the draggable.
	 * It is recommended to include some sort of well-defined discriminator and type guards to assist in narrowing the type.
	 */
	data: DraggableDataType;

	/**
	 * Optional.  Invoked when dragging begins.
	 */
	onDragStart?: DragStartCallbackT<DraggableDataType>;

	/**
	 * Optional. Invoked when dragging ends.
	 */
	onDragEnd?: DragEndCallbackT<DraggableDataType>;

	/**
	 * Returns a boolean signal dictating if the draggable is allowed to be dropped into this zone.
	 * NOTE: This method is invoked when dragging begins for each drop zone.
	 */
	canDrop?: DragDropPredicateT<DraggableDataType, DropzoneDataType>;

	/** Optional. Called when a draggable is dropped into a zone. */
	onDragDrop?: DragDropCallbackT<DraggableDataType, DropzoneDataType>;
}

export interface DropzonePropsT<DraggableDataType, DropzoneDataType> extends DropzoneProps {
	/**
	 * The payload of the draggable.  This typically contains data specific to the draggable.
	 * It is recommended to include some sort of well-defined discriminator and type guards to assist in narrowing the type.
	 */
	data: DropzoneDataType;

	/**
	 * Returns a boolean signal dictating if the draggable is allowed to be dropped into this zone.
	 * NOTE: This method is invoked when dragging begins.
	 */
	canDrop?: DragDropPredicateT<DraggableDataType, DropzoneDataType>;

	/** Optional. Called when a draggable is dropped into this zone. */
	onDragDrop?: DragDropCallbackT<DraggableDataType, DropzoneDataType>;

	/**
	 * Optional.  Invoked when a draggable is over a zone.
	 * NOTE: The order of these callbacks for nested zones is not guarenteed.
	 * NOTE: For nested zones, when leaving a nested, `onOver` is not invoked for the parent zone a second time.
	 */
	onDragOver?: (
		draggable: DraggableDataT<DraggableDataType>,
		dropzone: DropzoneDataT<DropzoneDataType>,
		x: number,
		y: number,
	) => void;

	/**
	 * Optional. Invoked when a draggable leaves the zone.
	 * NOTE: The order of these callbacks for nested zones is not guarenteed.
	 * NOTE: When entering a nested tooltip, this callback is not invoked for the parent.
	 */
	onDragLeave?: (
		draggable: DraggableDataT<DraggableDataType>,
		dropzone: DropzoneDataT<DropzoneDataType>,
		x: number,
		y: number,
	) => void; // Called when a draggable leaves this zone
}

export function createTypedDraggable<T>() {
	return (props: ParentProps<DraggableProps & { data: T }>) => Draggable(props);
}

export function createTypedDropzone<T>() {
	return (props: ParentProps<DropzoneProps & { data: T }>) => Dropzone(props);
}

export function createTypedDragAndDrop<DraggableDataType, DropzoneDataType>(): [
	ParentComponent<DragAndDropProps>,
	ParentComponent<DraggablePropsT<DraggableDataType, DropzoneDataType>>,
	ParentComponent<DropzonePropsT<DraggableDataType, DropzoneDataType>>,
] {
	return [
		DragAndDrop,
		(props: ParentProps<DraggablePropsT<DraggableDataType, DropzoneDataType>>) => Draggable(props),
		(props: ParentProps<DropzonePropsT<DraggableDataType, DropzoneDataType>>) => Dropzone(props),
	];
}
//#endregion
